package com.example.meetomxh.repositories;
import com.example.meetomxh.models.*;
import com.example.meetomxh.supabase.*;
import org.json.*;
import java.util.*;
public final class ChatRepository {
 public static final int DEFAULT_MESSAGE_LIMIT=50;
 public interface OnChatListener{void onSuccess(Chat chat);void onError(String error);}
 public interface OnChatsListener{void onChats(List<Chat> chats);void onError(String error);}
 public interface OnMessagesListener{void onMessages(List<ChatMessage> messages);void onError(String error);}
 public interface OnMessageSentListener{void onSuccess(String messageId);void onError(String error);}
 public interface OnMessageActionListener{void onSuccess();void onError(String error);}
 public interface OnReadUpdateListener{void onComplete(boolean updated);void onError(String error);}
 public interface OnChatStateListener{void onState(Chat chat);void onError(String error);}
 public static class ReplyData {public final String messageId,senderId,preview;public ReplyData(String id,String sender,String text){messageId=id;senderId=sender;preview=text;}}
 private static final ChatRepository INSTANCE=new ChatRepository();public static ChatRepository getInstance(){return INSTANCE;}
 public Chat load(String id)throws Exception{
  Chat c=Dto.chat(RpcClient.object("get_conversation",Api.obj("p_conversation_id",id)));JSONArray members=(JSONArray)RpcClient.call("get_conversation_members",Api.obj("p_conversation_id",id));List<String> ids=new ArrayList<>();for(int i=0;i<members.length();i++)ids.add(members.getJSONObject(i).getString("user_id"));c.setParticipants(ids);setMuteState(c);
  JSONObject page=RpcClient.object("get_messages",Api.obj("p_conversation_id",id,"p_limit",100));JSONArray messages=page.getJSONArray("items");JSONArray markers=(JSONArray)SupabaseHttpClient.authorized("GET","/rest/v1/conversation_members?conversation_id=eq."+id+"&select=user_id,last_read_seq,last_delivered_seq",null);
  Map<String,Long> readSeqs=new HashMap<>();Map<String,ServerTime> readAt=new HashMap<>();Map<String,String> readIds=new HashMap<>();Map<String,ServerTime> incomingAt=new HashMap<>();Map<String,String> incomingIds=new HashMap<>();String self=SessionManager.getInstance().uid();
  for(int j=0;j<markers.length();j++){JSONObject marker=markers.getJSONObject(j);long read=marker.optLong("last_read_seq");readSeqs.put(marker.getString("user_id"),read);for(int i=0;i<messages.length();i++){JSONObject m=messages.getJSONObject(i);if(m.optLong("seq")<=read){readAt.put(marker.getString("user_id"),ServerTime.parse(m.optString("created_at")));readIds.put(marker.getString("user_id"),m.optString("id"));break;}}}
  for(int i=0;i<messages.length();i++){JSONObject m=messages.getJSONObject(i);if(!self.equals(m.optString("sender_id"))){incomingAt.put(self,ServerTime.parse(m.optString("created_at")));incomingIds.put(self,m.optString("id"));break;}}
  for(int i=0;i<members.length();i++){JSONObject member=members.getJSONObject(i);c.memberNames.put(member.getString("user_id"),ChatCustomizationClient.name(member));}
  c.setLastReadSeqByUid(readSeqs);c.setLastReadAtByUid(readAt);c.setLastReadMessageIdByUid(readIds);c.setLastIncomingMessageAtByUid(incomingAt);c.setLastIncomingMessageIdByUid(incomingIds);return c;
 }
 public void getOrCreatePrivateChat(String peer,OnChatListener cb){Api.run(()->load(RpcClient.object("get_or_create_private",Api.obj("p_peer",peer)).getString("id")),new Api.Callback<Chat>(){public void success(Chat c){cb.onSuccess(c);}public void error(String e){cb.onError(e);}});}
 public void getChat(String id,OnChatListener cb){Api.run(()->load(id),new Api.Callback<Chat>(){public void success(Chat c){cb.onSuccess(c);}public void error(String e){cb.onError(e);}});}
 public Subscription listenToCurrentUserChats(OnChatsListener cb){return new com.example.meetomxh.supabase.Observer<>(()->{List<Chat> result=new ArrayList<>();JSONObject cursor=Api.obj("p_limit",50,"p_include_archived",true);for(int page=0;page<20;page++){JSONArray rows=(JSONArray)RpcClient.call("get_inbox",cursor);for(int i=0;i<rows.length();i++){Chat chat=Dto.chat(rows.getJSONObject(i));JSONArray members=(JSONArray)RpcClient.call("get_conversation_members",Api.obj("p_conversation_id",chat.getChatId()));List<String> ids=new ArrayList<>();for(int j=0;j<members.length();j++)ids.add(members.getJSONObject(j).getString("user_id"));chat.setParticipants(ids);setMuteState(chat);result.add(chat);}if(rows.length()<50)break;JSONObject last=rows.getJSONObject(rows.length()-1);cursor.put("p_after_time",last.getString("updated_at")).put("p_after_id",last.getString("id"));}return result;},new Api.Callback<List<Chat>>(){public void success(List<Chat> rows){cb.onChats(rows);}public void error(String e){cb.onChats(new ArrayList<>());cb.onError(e);}});}
 public void loadCurrentUserChats(OnChatsListener cb){Api.run(()->{List<Chat> result=new ArrayList<>();JSONArray rows=(JSONArray)RpcClient.call("get_inbox",Api.obj("p_limit",50,"p_include_archived",false));for(int i=0;i<rows.length();i++){Chat chat=Dto.chat(rows.getJSONObject(i));JSONArray members=(JSONArray)RpcClient.call("get_conversation_members",Api.obj("p_conversation_id",chat.getChatId()));List<String> ids=new ArrayList<>();for(int j=0;j<members.length();j++)ids.add(members.getJSONObject(j).getString("user_id"));chat.setParticipants(ids);setMuteState(chat);result.add(chat);}return result;},new Api.Callback<List<Chat>>(){public void success(List<Chat> rows){cb.onChats(rows);}public void error(String e){cb.onError(e);}});}
 public Subscription listenToChatState(String id,OnChatStateListener cb){return new com.example.meetomxh.supabase.Observer<>(()->load(id),new Api.Callback<Chat>(){public void success(Chat c){cb.onState(c);}public void error(String e){cb.onError(e);}});}
 public List<ChatMessage> history(String id,int limit)throws Exception{List<ChatMessage> result=new ArrayList<>();JSONObject cursor=Api.obj("p_conversation_id",id,"p_limit",Math.min(100,limit));for(int page=0;result.size()<limit;page++){JSONArray rows=RpcClient.object("get_messages",cursor).getJSONArray("items");for(int i=0;i<rows.length();i++)result.add(Dto.message(rows.getJSONObject(i)));if(rows.length()<cursor.getInt("p_limit"))break;cursor.put("p_before_seq",rows.getJSONObject(rows.length()-1).getLong("seq"));cursor.put("p_limit",Math.min(100,limit-result.size()));}result.sort(Comparator.comparingLong(m->m.seq));return result;}
 public Subscription listenToMessages(String id,OnMessagesListener cb){return listenToMessages(id,50,cb);}
 public Subscription listenToMessages(String id,int limit,OnMessagesListener cb){final long[] floor={0};return new com.example.meetomxh.supabase.Observer<>(()->{
  List<ChatMessage> rows;
  if(floor[0]==0){rows=history(id,limit);if(!rows.isEmpty())floor[0]=rows.get(0).seq;}
  else {rows=new ArrayList<>();long cursor=floor[0]-1;while(true){JSONObject page=RpcClient.object("get_messages",Api.obj("p_conversation_id",id,"p_after_seq",cursor,"p_limit",100));JSONArray items=page.getJSONArray("items");for(int i=0;i<items.length();i++)rows.add(Dto.message(items.getJSONObject(i)));if(items.length()==0||items.length()<100)break;cursor=items.getJSONObject(items.length()-1).getLong("seq");}}
  // Fixed oldest loaded sequence preserves the window during concurrent sends.
  // Each pass replaces it from current RLS truth, also removing old hidden/recalled rows.
  String self=SessionManager.getInstance().uid();for(int i=rows.size()-1;i>=0;i--)if(!self.equals(rows.get(i).getSenderId())){RpcClient.call("acknowledge_delivery",Api.obj("p_conversation_id",id,"p_message_id",rows.get(i).getMessageId()));break;}return rows;},new Api.Callback<List<ChatMessage>>(){public void success(List<ChatMessage> rows){cb.onMessages(rows);}public void error(String e){cb.onMessages(new ArrayList<>());cb.onError(e);}});}
 public void markChatRead(String id,String messageId,OnReadUpdateListener cb){Api.run(()->RpcClient.call("mark_read",Api.obj("p_conversation_id",id,"p_message_id",messageId)),new Api.Callback<Object>(){public void success(Object v){cb.onComplete(true);}public void error(String e){cb.onError(e);}});}
 public void sendTextMessage(String id,String text,OnMessageSentListener cb){sendTextMessage(id,text,null,cb);}
 public void sendTextMessage(String id,String text,ReplyData reply,OnMessageSentListener cb){send(id,"text",text,new JSONArray(),reply==null?null:reply.messageId,cb);}
 public void sendImageMessage(String id,String reference,OnMessageSentListener cb){sendImageMessage(id,reference,"",null,cb);}
 public void sendImageMessage(String id,String reference,String body,ReplyData reply,OnMessageSentListener cb){send(id,"media",body,Api.array(Dto.assetId(reference)),reply==null?null:reply.messageId,cb);}
 public void sendVoiceMessage(String id,String reference,ReplyData reply,OnMessageSentListener cb){send(id,"voice","",Api.array(Dto.assetId(reference)),reply==null?null:reply.messageId,cb);}
 private void send(String id,String kind,String body,JSONArray assets,String reply,OnMessageSentListener cb){JSONObject input=Api.obj("p_conversation_id",id,"p_kind",kind,"p_body",body,"p_assets",assets,"p_reply_to",reply);String fingerprint=input.toString();Api.run(()->{input.put("p_client_request_id",RequestIds.get("message",fingerprint));MessageOutbox.put(input);JSONObject result=RpcClient.object("send_message",input);MessageOutbox.done(input.getString("p_client_request_id"));RequestIds.complete("message",fingerprint);return result.getString("id");},new Api.Callback<String>(){public void success(String messageId){cb.onSuccess(messageId);RealtimeClient.get().connect();}public void error(String e){cb.onError(e);}});}
 public void recallMessage(String id,ChatMessage message,OnMessageActionListener cb){action("recall_message",Api.obj("p_message_id",message.getMessageId()),cb);}
 public void deleteMessageForMe(String id,ChatMessage message,OnMessageActionListener cb){action("hide_message_for_me",Api.obj("p_message_id",message.getMessageId()),cb);}
 public void editMessage(ChatMessage message,String body,OnMessageActionListener cb){if(message==null){cb.onError("Tin nhắn không khả dụng.");return;}action("edit_message",Api.obj("p_message_id",message.getMessageId(),"p_body",body,"p_expected_version",message.version),cb);}
 public void forwardTextMessage(String sourceId,String targetId,OnMessageActionListener cb){String requestId=UUID.randomUUID().toString();Api.run(()->RpcClient.call("forward_text_message",Api.obj("p_source_message_id",sourceId,"p_target_conversation_id",targetId,"p_client_request_id",requestId)),new Api.Callback<Object>(){public void success(Object value){cb.onSuccess();}public void error(String error){cb.onError(error);}});}
 public void searchConversations(String query,boolean archived,OnChatsListener cb){Api.run(()->{List<Chat> result=new ArrayList<>();Set<String> seen=new HashSet<>();String time=null,id=null;while(true){JSONArray rows=(JSONArray)RpcClient.call("search_conversations_v36",Api.obj("p_query",query,"p_archived",archived,"p_after_time",time,"p_after_id",id,"p_limit",30));for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);Chat chat=Dto.chat(row);if(!seen.add(chat.getChatId()))continue;JSONArray members=(JSONArray)RpcClient.call("get_conversation_members",Api.obj("p_conversation_id",chat.getChatId()));List<String> ids=new ArrayList<>();for(int j=0;j<members.length();j++)ids.add(members.getJSONObject(j).getString("user_id"));chat.setParticipants(ids);setMuteState(chat);result.add(chat);}if(rows.length()<30)break;JSONObject last=rows.getJSONObject(rows.length()-1);time=last.getString("updated_at");id=last.getString("id");Api.checkCancelled();}return result;},new Api.Callback<List<Chat>>(){public void success(List<Chat> rows){cb.onChats(rows);}public void error(String error){cb.onError(error);}});}
 private void setMuteState(Chat chat)throws Exception{chat.muted=RpcClient.object("get_conversation_mute",Api.obj("p_conversation_id",chat.getChatId())).optBoolean("muted",false);}
 public void action(String rpc,JSONObject input,OnMessageActionListener cb){Api.run(()->RpcClient.call(rpc,input),new Api.Callback<Object>(){public void success(Object v){cb.onSuccess();}public void error(String e){cb.onError(e);}});}
 public void search(String id,String query,OnMessagesListener cb){Api.run(()->{JSONArray rows=RpcClient.object("search_messages",Api.obj("p_conversation_id",id,"p_query",query,"p_limit",100)).getJSONArray("items");List<ChatMessage> found=new ArrayList<>();for(int i=0;i<rows.length();i++)found.add(Dto.message(rows.getJSONObject(i)));return found;},new Api.Callback<List<ChatMessage>>(){public void success(List<ChatMessage> rows){cb.onMessages(rows);}public void error(String e){cb.onError(e);}});}
 public static boolean isValidStorageMediaReference(String reference){try{java.util.UUID.fromString(Dto.assetId(reference));return reference.startsWith("asset://");}catch(Exception e){return false;}}
}
